// Shop Floor engine - a tiny flat-shaded low-poly renderer on Canvas2D.
//
// Why not three.js: the desktop loader resolves only @hermes/plugin-sdk + react, and a
// ~650 KB bundled engine is hard to review. The scene is ~1.5k faces, so a painter's-
// sorted Canvas2D renderer is fast, GPU-free and fully deterministic (headless-testable).
//
// Data: SCENE_DATA (generated by assets/blender/build_meshes.py). World is Y-up.
// State in: the GET /floor payload. Nothing here is a source of truth - the scene only
// mirrors backend state and animates between snapshots.

import { SCENE_DATA } from './meshes.generated.js'

const DEG = Math.PI / 180
export const TOKEN_COLORS = {
  red: '#e0566d', white: '#fbf8f3', pink: '#f3a5bf', yellow: '#f3c444', peach: '#f6b48f',
  lilac: '#c9b8e8', purple: '#b59ad6', orange: '#f2a07b', blue: '#9cc6ea', green: '#9fd39a', mixed: '#e57c93'
}
export const STATION_TINTS = {
  incoming: '#c9b8e8', prep: '#f2c48d', assembly: '#f0a5b4', quality: '#a9d8b8', packing: '#a8cdea', delivery: '#9ed2c6'
}
const LATE = '#e5484d'
const LIGHT = norm([-0.45, 0.85, 0.35])
const FILL = norm([0.6, 0.35, -0.5])

function norm(v) { const l = Math.hypot(v[0], v[1], v[2]) || 1; return [v[0] / l, v[1] / l, v[2] / l] }
function hexRgb(h) { const n = parseInt(String(h).replace('#', '').slice(0, 6), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255] }
function clamp(x, a, b) { return x < a ? a : x > b ? b : x }
function lerp(a, b, t) { return a + (b - a) * t }
function ease(t) { return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2 }

// ---- mesh preparation ---------------------------------------------------------------
export function prepareMeshes(data) {
  const palette = data.palette.map(hexRgb)
  const tintIdx = data.paletteKeys.indexOf('tint')
  const tint2Idx = data.paletteKeys.indexOf('tint2')
  const meshes = {}
  for (const [name, m] of Object.entries(data.meshes)) {
    const v = m.v
    const faces = []
    for (const f of m.f) {
      const col = f[0]
      const idx = f.slice(1)
      if (idx.length < 3) continue
      // Newell normal (robust for n-gons)
      let nx = 0, ny = 0, nz = 0, cx = 0, cy = 0, cz = 0
      for (let i = 0; i < idx.length; i++) {
        const a = idx[i] * 3, b = idx[(i + 1) % idx.length] * 3
        nx += (v[a + 1] - v[b + 1]) * (v[a + 2] + v[b + 2])
        ny += (v[a + 2] - v[b + 2]) * (v[a] + v[b])
        nz += (v[a] - v[b]) * (v[a + 1] + v[b + 1])
        cx += v[a]; cy += v[a + 1]; cz += v[a + 2]
      }
      const n = norm([nx, ny, nz])
      faces.push({ col, idx, n, c: [cx / idx.length, cy / idx.length, cz / idx.length] })
    }
    // bounding radius for culling/picking
    let r = 0, top = 0
    for (let i = 0; i < v.length; i += 3) { r = Math.max(r, Math.hypot(v[i], v[i + 2])); top = Math.max(top, v[i + 1]) }
    meshes[name] = { v, faces, radius: r, top }
  }
  return { meshes, palette, tintIdx, tint2Idx }
}

// ---- camera -----------------------------------------------------------------------------
export function makeCamera(yaw, pitch, zoom, w, h) {
  const f = [Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), Math.cos(yaw) * Math.cos(pitch)]
  const r = norm([f[2], 0, -f[0]])
  const u = [f[1] * r[2] - f[2] * r[1], f[2] * r[0] - f[0] * r[2], f[0] * r[1] - f[1] * r[0]]
  // fit: island radius 6.25 plus ~2.6 units of props above it, with a margin
  const scale = (Math.min(w / 14.6, h / (13.4 * Math.sin(pitch) + 4.2))) * zoom * 1.14
  return { f, r, u, scale, cx: w / 2, cy: h / 2 + h * 0.05, target: [0, 0.6, 0.2] }
}

export function project(cam, p) {
  const x = p[0] - cam.target[0], y = p[1] - cam.target[1], z = p[2] - cam.target[2]
  const vx = x * cam.r[0] + y * cam.r[1] + z * cam.r[2]
  const vy = x * cam.u[0] + y * cam.u[1] + z * cam.u[2]
  const vz = x * cam.f[0] + y * cam.f[1] + z * cam.f[2]
  return [cam.cx + vx * cam.scale, cam.cy - vy * cam.scale, vz]
}

// ---- scene layout -------------------------------------------------------------------------
export function stationMap() {
  const m = {}
  for (const s of SCENE_DATA.layout.stations) m[s.id] = s
  return m
}

/** Target slot for the i-th token at a station: fanned around the CAMERA side of the pad
 *  (+z), so props (placed behind the pad centre) never hide a token. Second row further out. */
const FAN = [0, -38, 38, -76, 76, -114, 114]
export function tokenSlot(stationPos, i) {
  const ring = i < FAN.length ? 0 : 1
  const k = ring === 0 ? i : (i - FAN.length) % 9
  const a = (90 + (ring === 0 ? FAN[k] : -120 + k * 30)) * DEG
  const radius = ring === 0 ? 0.88 : 1.3
  return [stationPos[0] + Math.cos(a) * radius, 0.2, stationPos[2] + Math.sin(a) * radius]
}

// ---- renderer -----------------------------------------------------------------------------
export function createRenderer(canvas, opts = {}) {
  const prep = prepareMeshes(SCENE_DATA)
  const ctx = canvas.getContext('2d')
  const stations = stationMap()
  const reduceMotion = !!opts.reduceMotion
  const st = {
    yaw: -35 * DEG, pitch: 36 * DEG, zoom: 1, w: 1, h: 1, dpr: 1,
    tokens: new Map(), // order id -> {id, from, to, t0, dur, tint, late, label, station, phase}
    selectedId: null, hoverId: null,
    mascot: { pos: [0, 0.08, 0.9], rot: -0.6, target: null, walkT: 0, wave: 0 },
    stationCounts: {}, empty: true, theme: { text: '#c8c8cc', muted: '#8a8a92', font: 'sans-serif', card: 'rgba(20,20,24,0.78)' },
    lastFrame: 0, screenTokens: []
  }

  const statics = [{ mesh: 'island', pos: [0, 0, 0], rot: 0, scale: 1, layer: 0 },
    { mesh: 'shop', pos: [SCENE_DATA.layout.shop[0], 0.06, SCENE_DATA.layout.shop[2]], rot: 0, scale: 1 }]
  for (const s of SCENE_DATA.layout.stations) {
    statics.push({ mesh: 'pad', pos: [s.pos[0], 0, s.pos[2]], rot: 0, scale: 1, tint: STATION_TINTS[s.id], layer: 1 })
    const facing = Math.atan2(s.pos[0], s.pos[2]) * 0.3
    statics.push({ mesh: 'prop_' + s.id, pos: [s.pos[0] - 0.15, 0.2, s.pos[2] - 0.25], rot: facing, scale: 1 })
  }
  for (const d of SCENE_DATA.layout.decor) statics.push({ mesh: d.mesh, pos: [d.pos[0], 0.06, d.pos[2]], rot: -d.rot * DEG, scale: d.scale })
  if (opts.solo) { statics.length = 0; statics.push({ mesh: opts.solo, pos: [0, 0, 0], rot: 0, scale: opts.soloScale || 3 }) } // debug/test only

  function resize(w, h, dpr) {
    st.w = Math.max(1, w); st.h = Math.max(1, h); st.dpr = dpr || 1
    canvas.width = Math.round(st.w * st.dpr); canvas.height = Math.round(st.h * st.dpr)
  }

  function setTheme(theme) { Object.assign(st.theme, theme || {}) }

  /** Mirror a GET /floor payload. Tokens that changed station fly there; mascot follows. */
  function setFloor(floor, now) {
    const orders = (floor && floor.orders) || []
    const byStation = {}
    for (const o of orders) (byStation[o.station] = byStation[o.station] || []).push(o)
    const seen = new Set()
    let moved = null
    for (const [sid, list] of Object.entries(byStation)) {
      const s = stations[sid]
      if (!s) continue
      list.forEach((o, i) => {
        seen.add(o.id)
        const to = tokenSlot(s.pos, i)
        const tint = TOKEN_COLORS[String(o.color || 'mixed').toLowerCase()] || TOKEN_COLORS.mixed
        const label = o.order_number + (o.customer_name ? ' - ' + o.customer_name : '')
        const prev = st.tokens.get(o.id)
        if (!prev) {
          st.tokens.set(o.id, { id: o.id, from: [to[0], to[1] + 1.2, to[2]], to, t0: now, dur: 700, tint, late: !!o.is_late,
            label, station: sid, phase: (o.id * 1.37) % 6.28, arc: 0 })
        } else {
          const changed = prev.station !== sid
          const cur = tokenPos(prev, now)
          if (changed || prev.to[0] !== to[0] || prev.to[2] !== to[2]) {
            Object.assign(prev, { from: cur, to, t0: now, dur: changed ? 1400 : 500, arc: changed ? 0.9 : 0 })
            if (changed) moved = sid
          }
          Object.assign(prev, { tint, late: !!o.is_late, label, station: sid })
        }
      })
    }
    for (const id of [...st.tokens.keys()]) if (!seen.has(id)) st.tokens.delete(id)
    st.stationCounts = {}
    for (const s of (floor && floor.stations) || []) st.stationCounts[s.id] = { count: s.count, late: s.late, label: s.label }
    st.empty = orders.length === 0
    if (moved) sendMascot(moved)
    else if (!st.mascot.target && orders.length) {
      const busiest = Object.entries(byStation).sort((a, b) => b[1].length - a[1].length)[0]
      if (busiest) sendMascot(busiest[0])
    }
  }

  function sendMascot(stationId) {
    const s = stations[stationId]
    if (!s) return
    // stand between the pad and the island centre, on the camera side, so nothing hides it
    st.mascot.target = [s.pos[0] * 0.66, 0.08, s.pos[2] * 0.66 + 0.85]
  }

  function setSelected(id) {
    st.selectedId = id == null ? null : id
    const t = id == null ? null : st.tokens.get(id)
    if (t) sendMascot(t.station)
  }

  function tokenPos(t, now) {
    const k = clamp((now - t.t0) / t.dur, 0, 1)
    const e = reduceMotion ? 1 : ease(k)
    return [lerp(t.from[0], t.to[0], e), lerp(t.from[1], t.to[1], e) + Math.sin(Math.PI * e) * (t.arc || 0), lerp(t.from[2], t.to[2], e)]
  }

  function step(dt, now) {
    const m = st.mascot
    if (m.target) {
      const dx = m.target[0] - m.pos[0], dz = m.target[2] - m.pos[2]
      const d = Math.hypot(dx, dz)
      if (d < 0.03 || reduceMotion) {
        if (reduceMotion) { m.pos[0] = m.target[0]; m.pos[2] = m.target[2] }
        m.target = null; m.walkT = 0; m.wave = 1
      } else {
        const sp = Math.min(d, 1.9 * dt)
        m.pos[0] += dx / d * sp; m.pos[2] += dz / d * sp
        m.walkT += dt
        const want = Math.atan2(dx, dz)
        let diff = want - m.rot
        while (diff > Math.PI) diff -= 2 * Math.PI
        while (diff < -Math.PI) diff += 2 * Math.PI
        m.rot += diff * Math.min(1, dt * 8)
      }
    } else if (m.wave > 0) {
      m.wave = Math.max(0, m.wave - dt * 0.8)
      // turn to face the camera while celebrating
      let diff = (st.yaw) - m.rot
      while (diff > Math.PI) diff -= 2 * Math.PI
      while (diff < -Math.PI) diff += 2 * Math.PI
      m.rot += diff * Math.min(1, dt * 4)
    }
  }

  function instanceFaces(cam, inst, out, now) {
    const mesh = prep.meshes[inst.mesh]
    if (!mesh) return
    const cr = Math.cos(inst.rot || 0), sr = Math.sin(inst.rot || 0)
    const s = inst.scale || 1
    const sy = inst.sy || 1
    const v = mesh.v
    const n = v.length / 3
    const P = inst._buf && inst._buf.length === n * 3 ? inst._buf : (inst._buf = new Float32Array(n * 3))
    const Y = inst._ybuf && inst._ybuf.length === n ? inst._ybuf : (inst._ybuf = new Float32Array(n))
    for (let i = 0; i < n; i++) {
      const x = v[i * 3] * s, y = v[i * 3 + 1] * s * sy, z = v[i * 3 + 2] * s
      const wx = x * cr + z * sr + inst.pos[0]
      const wz = -x * sr + z * cr + inst.pos[2]
      const wy = y + inst.pos[1]
      const pr = project(cam, [wx, wy, wz])
      P[i * 3] = pr[0]; P[i * 3 + 1] = pr[1]; P[i * 3 + 2] = pr[2]; Y[i] = wy
    }
    // Draw layers: 0 ground, 1 pads (both ordered by HEIGHT - large flat polygons break a
    // centroid depth sort), 2 objects (ordered by depth).
    const layer = inst.layer == null ? 2 : inst.layer
    const tint = inst.tint ? hexRgb(inst.tint) : null
    for (const f of mesh.faces) {
      const nx = f.n[0] * cr + f.n[2] * sr, ny = f.n[1], nz = -f.n[0] * sr + f.n[2] * cr
      if (nx * cam.f[0] + ny * cam.f[1] + nz * cam.f[2] <= 0.0001) continue // back-face cull
      let rgb = prep.palette[f.col]
      if (f.col === prep.tintIdx) rgb = tint || rgb
      else if (f.col === prep.tint2Idx) rgb = inst.tint2 ? hexRgb(inst.tint2) : [243, 196, 68]
      const diff = Math.max(0, nx * LIGHT[0] + ny * LIGHT[1] + nz * LIGHT[2])
      const fill = Math.max(0, nx * FILL[0] + ny * FILL[1] + nz * FILL[2])
      const k = 0.52 + diff * 0.5 + fill * 0.12 + (ny > 0 ? ny * 0.06 : 0)
      let depth = 0, hy = 0
      const pts = new Array(f.idx.length * 2)
      for (let j = 0; j < f.idx.length; j++) {
        const q = f.idx[j] * 3
        pts[j * 2] = P[q]; pts[j * 2 + 1] = P[q + 1]; depth += P[q + 2]; hy += Y[f.idx[j]]
      }
      depth = depth / f.idx.length + (inst.bias || 0)
      hy /= f.idx.length
      out.push({ pts, depth: layer * 1e6 + (layer < 2 ? hy * 1000 + depth * 0.01 : depth),
        fill: 'rgb(' + Math.min(255, rgb[0] * k | 0) + ',' + Math.min(255, rgb[1] * k | 0) + ',' + Math.min(255, rgb[2] * k | 0) + ')' })
    }
  }

  function frame(now) {
    const dt = st.lastFrame ? Math.min(0.1, (now - st.lastFrame) / 1000) : 0.016
    st.lastFrame = now
    step(dt, now)
    const W = st.w * st.dpr, H = st.h * st.dpr
    const cam = makeCamera(st.yaw, st.pitch, st.zoom, W, H)
    const polys = []
    for (const inst of statics) instanceFaces(cam, inst, polys, now)
    const screenTokens = []
    for (const t of st.tokens.values()) {
      const p = tokenPos(t, now)
      const bob = reduceMotion ? 0 : Math.sin(now / 520 + t.phase) * 0.035
      const sel = st.selectedId === t.id
      const inst = { mesh: 'bouquet', pos: [p[0], p[1] + bob + (sel ? 0.12 : 0), p[2]], rot: t.phase, scale: sel ? 1.85 : 1.5,
        tint: t.tint, tint2: '#f3c444', bias: 0.02 }
      instanceFaces(cam, inst, polys, now)
      const head = project(cam, [p[0], p[1] + (sel ? 1.1 : 0.9) + bob, p[2]])
      const base = project(cam, [p[0], p[1], p[2]])
      screenTokens.push({ id: t.id, x: head[0], y: head[1], bx: base[0], by: base[1], z: head[2], late: t.late, label: t.label, sel })
    }
    // mascot: hop while walking, idle sway, little celebration wave
    const m = st.mascot
    const walking = !!m.target
    const hop = walking && !reduceMotion ? Math.abs(Math.sin(m.walkT * 9)) * 0.12 : 0
    const sway = reduceMotion ? 0 : Math.sin(now / 900) * (walking ? 0.05 : 0.08) + (m.wave > 0 ? Math.sin(now / 90) * 0.12 * m.wave : 0)
    instanceFaces(cam, { mesh: 'mascot', pos: [m.pos[0], m.pos[1] + hop, m.pos[2]], rot: m.rot + sway, scale: 1.6,
      sy: walking && !reduceMotion ? 1 - hop * 0.6 : 1 }, polys, now)

    polys.sort((a, b) => a.depth - b.depth)
    ctx.setTransform(1, 0, 0, 1, 0, 0)
    ctx.clearRect(0, 0, W, H)
    // soft contact shadow under the island
    const sh = project(cam, [0, -0.75, 0])
    ctx.save()
    ctx.globalAlpha = 0.28
    ctx.fillStyle = '#000'
    ctx.beginPath()
    ctx.ellipse(sh[0], sh[1] + 8 * st.dpr, 6.6 * cam.scale, 6.6 * cam.scale * Math.sin(st.pitch) * 0.9, 0, 0, Math.PI * 2)
    ctx.filter = 'blur(' + (14 * st.dpr) + 'px)'
    ctx.fill()
    ctx.restore()
    ctx.lineJoin = 'round'
    ctx.lineWidth = 0.8 * st.dpr
    for (const p of polys) {
      const a = p.pts
      ctx.beginPath()
      ctx.moveTo(a[0], a[1])
      for (let i = 2; i < a.length; i += 2) ctx.lineTo(a[i], a[i + 1])
      ctx.closePath()
      ctx.fillStyle = p.fill
      ctx.strokeStyle = p.fill
      ctx.fill()
      ctx.stroke()
    }
    drawOverlay(cam, screenTokens)
    st.screenTokens = screenTokens
  }

  function pill(x, y, text, opts2) {
    const d = st.dpr
    ctx.font = (opts2.weight || 500) + ' ' + (opts2.size || 11) * d + 'px ' + st.theme.font
    const w = ctx.measureText(text).width + 12 * d
    const h = (opts2.size || 11) * d + 8 * d
    ctx.fillStyle = opts2.bg
    ctx.beginPath()
    if (ctx.roundRect) ctx.roundRect(x - w / 2, y - h / 2, w, h, h / 2)
    else ctx.rect(x - w / 2, y - h / 2, w, h)
    ctx.fill()
    ctx.fillStyle = opts2.fg
    ctx.textAlign = 'center'
    ctx.textBaseline = 'middle'
    ctx.fillText(text, x, y + 0.5 * d)
  }

  function drawOverlay(cam, screenTokens) {
    const d = st.dpr
    // station labels just in front of each pad
    for (const s of SCENE_DATA.layout.stations) {
      const p = project(cam, [s.pos[0], 0.05, s.pos[2] + 1.15])
      const c = st.stationCounts[s.id] || { count: 0, late: 0 }
      const text = s.label + '  ' + (c.count || 0)
      pill(p[0], p[1], text, { bg: st.theme.card, fg: c.late ? '#ffb4b4' : st.theme.text, size: 10.5 })
    }
    // late markers + selection + hover label
    for (const t of screenTokens) {
      if (t.late) {
        ctx.fillStyle = LATE
        ctx.beginPath(); ctx.arc(t.x + 11 * d, t.y - 11 * d, 8 * d, 0, Math.PI * 2); ctx.fill()
        ctx.fillStyle = '#fff'; ctx.font = '700 ' + 9 * d + 'px ' + st.theme.font
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText("!", t.x + 11 * d, t.y - 10.5 * d)
      }
      if (t.sel) {
        ctx.strokeStyle = st.theme.text; ctx.lineWidth = 1.5 * d
        ctx.beginPath()
        ctx.ellipse(t.bx, t.by, 0.36 * cam.scale, 0.36 * cam.scale * Math.sin(st.pitch), 0, 0, Math.PI * 2)
        ctx.stroke()
      }
      if (t.sel || st.hoverId === t.id) pill(t.x, t.y - 20 * d, t.label, { bg: st.theme.card, fg: st.theme.text, size: 11, weight: 600 })
    }
    if (st.empty) {
      const p = project(cam, [st.mascot.pos[0], 1.6, st.mascot.pos[2]])
      pill(p[0], p[1], 'All quiet - no active orders', { bg: st.theme.card, fg: st.theme.muted, size: 11 })
    }
  }

  /** Token under a CSS-pixel point (nearest head within 20px, front-most wins). */
  function pick(x, y) {
    const d = st.dpr
    let best = null, bestScore = Infinity
    for (const t of st.screenTokens) {
      const dist = Math.hypot(t.x - x * d, (t.y + 10 * d) - y * d)
      if (dist < 24 * d) {
        const score = dist - t.z * 2
        if (score < bestScore) { bestScore = score; best = t.id }
      }
    }
    return best
  }

  return {
    resize, setTheme, setFloor, setSelected, frame, pick,
    setHover: id => { st.hoverId = id },
    rotate: (dYaw, dPitch) => { st.yaw += dYaw; st.pitch = clamp(st.pitch + dPitch, 18 * DEG, 62 * DEG) },
    zoomBy: f => { st.zoom = clamp(st.zoom * f, 0.6, 2.4) },
    resetView: () => { st.yaw = -35 * DEG; st.pitch = 36 * DEG; st.zoom = 1 },
    state: st
  }
}
